  }

  function updateLiveCount(){
    const startCount = 50;            // 目前起始報名人數，修改這裡
    const maxSeats = 100;             // 總席次
    const startDate = new Date('2026-07-19T00:00:00+08:00').getTime(); // 修改這裡：開始累積的基準日

    const now = Date.now();
    const hoursPassed = Math.floor((now - startDate) / (1000 * 60 * 60));

    // 每6小時 +1 人（約每天+4人）
    const increments = Math.floor(hoursPassed / 6);

    let current = startCount + increments;

    if(current > maxSeats){
      current = maxSeats;
    }

    ids.liveCount.textContent = current;
    ids.remainingCount.textContent = Math.max(0, maxSeats - current);
  }

  updateCountdown();
  updateLiveCount();
  setInterval(updateCountdown, 1000);
  setInterval(updateLiveCount, 60000);  // 每分鐘檢查一次人數變化
})();

