# Bot Relay Hook

每次 Bot 發出訊息時，把訊息寫入共享日誌檔讓子Bot讀取感知。

## 共享日誌格式
每次寫入一行 JSON：
```json
{"ts":"ISO時間","botId":"1","text":"訊息摘要","msgId":123}
```

## 日誌檔案
`~/.openclaw/workspace/BOT_MESSAGES.md`（所有Bot共享）
==========
"use strict";

const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const WORKSPACE = path.join(process.env.HOME, '.openclaw', 'workspace');
const LOG_FILE = path.join(WORKSPACE, 'BOT_MESSAGES.md');
const COUNCIL_TRIGGER = path.join(WORKSPACE, 'scripts', 'council_orchestrator.sh');

// v2.5 修補（2026-06-09）：botId 動態解析三層 fallback（event.agentId → ctx.agentId → sessionKey）
// v2.4 殘bug：message:sent event 的 ctx.agentId 是 undefined，導致全部寫 "unknown"
// v2.5 解法：抄 group-identity 的 sessionKey 解析（agent:<id>:<channel>:...）
const AGENT_NAME_MAP = { main: '🦞學長', kong: '🦐學弟', peipei: '🐰學妹' };

function resolveAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId ||
    ctx.agentId ||
    (ctx.agent && ctx.agent.id) ||
    ctx.agent ||
    '';
  if (raw) return String(raw).toLowerCase();
  const sessionKey = event.sessionKey || ctx.sessionKey || '';
  if (sessionKey) {
    const parts = String(sessionKey).split(':');
    if (parts[0] === 'agent' && parts[1]) return parts[1].toLowerCase();
  }
  return 'unknown';
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'sent') return;

  try {
    const ctx = event.context ?? {};
    const text = ctx.textContent ?? ctx.content ?? '';
    const msgId = ctx.messageId ?? ctx.id ?? 0;
    const chatId = ctx.chatId ?? '-1003877502911';
    const chatType = ctx.chatType ?? '';
    const agentId = resolveAgentId(event);

    // Skip empty or very short messages
    if (!text || text.trim().length < 2) return;

    // Only log messages in group chats (negative chatId)
    if (chatType === 'direct' || (typeof chatId === 'number' && chatId > 0)) return;

    const entry = {
      ts: new Date().toISOString(),
      botId: agentId,                                  // ← 改：動態 agentId（main/kong/peipei）
      botName: AGENT_NAME_MAP[agentId] || agentId,     // ← 新：人話名稱供 inbound 顯示
      text: text.substring(0, 200),
      msgId,
      chatId: String(chatId)
    };

    const line = JSON.stringify(entry) + '\n';

    fs.appendFileSync(LOG_FILE, line, 'utf8');

    // 方案 B（2026-06-09 教練親令）：學弟學妹 sent 時即時觸發 Council 收尾巡邏（不等 2 分鐘 cron）
    // 只對 kong/peipei 觸發，避免學長自己發訊息時自觸發循環
    // detached + unref + stdio:ignore = 完全背景跑，不阻塞 hook 主流程
    if ((agentId === 'kong' || agentId === 'peipei') && fs.existsSync(COUNCIL_TRIGGER)) {
      try {
        spawn(COUNCIL_TRIGGER, [], { detached: true, stdio: 'ignore' }).unref();
      } catch { /* silent */ }
    }
  } catch (err) {
    // Silent fail - don't disrupt message sending
  }
};

module.exports = handler;
module.exports.default = handler;

