"use strict";

// OpenClaw Hook：line-delivery-fallback
// 用途：bni_tainan LINE 回覆送出失敗（例如 reply token 過期）時，自動改用
//       LINE Push API 補送一次，避免 AI 反應慢時訊息默默消失。
// 事件：message:sent（照 bot-relay handler 模板，event.type==='message' && event.action==='sent'）
// 軍師建立 2026-07-24（教練回報「LINE沒收到回覆但網路後台看得到」後查證+動手修復）

const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const HOME = process.env.HOME;
const PROBE_LOG = path.join(HOME, '.openclaw', 'logs', 'line-delivery-fallback-probe.log');
const ACTION_LOG = path.join(HOME, '.openclaw', 'logs', 'line-delivery-fallback-action.log');
const PUSH_SCRIPT = path.join(HOME, '.openclaw', 'agents', 'bni_tainan', 'scripts', 'send_line_push.py');

// 同一則訊息避免重複補送（module-level，gateway 重啟會重置，可接受）
const recentlyPushed = new Map(); // key -> timestamp
const DEDUPE_WINDOW_MS = 5 * 60 * 1000;

function probeDump(event) {
  try {
    const ctx = (event && event.context) || {};
    const info = {
      ts: new Date().toISOString(),
      topKeys: Object.keys(event || {}),
      ctxKeys: Object.keys(ctx),
      success: event.success ?? ctx.success,
      to: event.to ?? ctx.to ?? ctx.chatId,
      sessionKey: event.sessionKey ?? ctx.sessionKey,
      error: event.error ?? ctx.error,
      contentPreview: String(event.content ?? ctx.content ?? ctx.textContent ?? '').slice(0, 60),
    };
    fs.appendFileSync(PROBE_LOG, JSON.stringify(info) + '\n');
  } catch (e) { /* silent */ }
}

function logAction(entry) {
  try {
    fs.appendFileSync(ACTION_LOG, JSON.stringify({ ts: new Date().toISOString(), ...entry }) + '\n');
  } catch (e) { /* silent */ }
}

function isBniTainanLine(event) {
  const ctx = (event && event.context) || {};
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const channel = String(event.channel ?? ctx.channel ?? '');
  const accountId = String(event.accountId ?? ctx.accountId ?? '');
  if (sessionKey.includes('bni_tainan') && sessionKey.includes('line')) return true;
  if (channel === 'line' && accountId === 'bni_tainan') return true;
  return false;
}

function wasSendFailure(event) {
  const ctx = (event && event.context) || {};
  const success = event.success ?? ctx.success;
  const error = event.error ?? ctx.error;
  if (success === false) return true;
  if (success === undefined && error) return true;
  return false;
}

function extractTarget(event) {
  const ctx = (event && event.context) || {};
  let to = event.to ?? ctx.to ?? ctx.chatId;
  if (to) return String(to);
  // fallback: derive LINE user id from sessionKey tail (agent:bni_tainan:line:direct:u...)
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  const parts = sessionKey.split(':');
  const tail = parts[parts.length - 1];
  if (tail && tail.length > 10) return tail;
  return '';
}

function extractContent(event) {
  const ctx = (event && event.context) || {};
  return String(event.content ?? ctx.content ?? ctx.textContent ?? '').trim();
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'sent') return;

  probeDump(event);

  if (!isBniTainanLine(event)) return;
  if (!wasSendFailure(event)) return;

  const target = extractTarget(event);
  const content = extractContent(event);
  if (!target || !content) {
    logAction({ outcome: 'skip_missing_fields', target, hasContent: !!content });
    return;
  }

  const dedupeKey = target + '|' + content.slice(0, 100);
  const now = Date.now();
  const last = recentlyPushed.get(dedupeKey);
  if (last && (now - last) < DEDUPE_WINDOW_MS) {
    logAction({ outcome: 'skip_dedupe', target });
    return;
  }
  recentlyPushed.set(dedupeKey, now);

  try {
    const child = spawn('python3', [PUSH_SCRIPT, '--to', target, '--message', content], {
      detached: true,
      stdio: 'ignore',
    });
    child.unref();
    logAction({ outcome: 'fallback_push_triggered', target, contentPreview: content.slice(0, 60) });
  } catch (e) {
    logAction({ outcome: 'fallback_push_spawn_error', target, error: String(e) });
  }
};

module.exports = handler;
module.exports.default = handler;

