const MAP_FILE = path.join(HOME, '.openclaw', 'workspace', 'state', 'bni_tainan_line_id_map.json');
const TOKEN_FILE = path.join(HOME, '.openclaw', 'credentials', 'line-bni_tainan-token.txt');
const DIRECTORY_FILE = path.join(HOME, '.openclaw', 'agents', 'bni_tainan', 'knowledge', 'member_directory.md');

function loadMap() {
  try {
    return JSON.parse(fs.readFileSync(MAP_FILE, 'utf8'));
  } catch (e) {
    return {};
  }
}

function saveMap(map) {
  try {
    fs.mkdirSync(path.dirname(MAP_FILE), { recursive: true });
    fs.writeFileSync(MAP_FILE, JSON.stringify(map, null, 2));
  } catch (e) { /* silent */ }
}

// 解析 member_directory.md 的 markdown table 行：| 姓名 | 專業 | 電話 | 合作對象 |
function loadDirectoryEntries() {
  try {
    const text = fs.readFileSync(DIRECTORY_FILE, 'utf8');
    const lines = text.split('\n');
    const entries = [];
    for (const line of lines) {
      const m = line.match(/^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*(09\d{8})\s*\|\s*([^|]+?)\s*\|$/);
      if (m) {
        entries.push({ name: m[1].trim(), profession: m[2].trim(), phone: m[3].trim(), target: m[4].trim() });
      }
    }
    return entries;
  } catch (e) {
    return [];
  }
}

function guessMember(displayName, statusMessage) {
  const haystack = `${displayName || ''} ${statusMessage || ''}`;
  const entries = loadDirectoryEntries();

  // 1. 完整姓名命中（最可信）
  for (const e of entries) {
    if (e.name.length >= 2 && haystack.includes(e.name)) {
      return { guessedMember: `${e.name}（${e.profession}）`, confidence: 'high_name_match' };
    }
  }
  // 2. 名字（去掉姓氏首字）命中——LINE暱稱常只打名不打姓，例如「柯朝陽」暱稱裡只有「朝陽」
  for (const e of entries) {
    const givenName = e.name.slice(1);
    if (givenName.length >= 2 && haystack.includes(givenName)) {
      return { guessedMember: `疑似${e.name}（${e.profession}，僅名字「${givenName}」命中，姓氏未確認）`, confidence: 'medium_given_name_match' };
    }
  }
  // 3. 專業類別詞命中（最弱訊號）
  for (const e of entries) {
    if (e.profession.length >= 2 && haystack.includes(e.profession)) {
      return { guessedMember: `疑似${e.name}（${e.profession}，僅專業關鍵字命中）`, confidence: 'low_profession_match' };
    }
  }
  return { guessedMember: null, confidence: 'unmatched' };
}

function fetchLineProfile(userId, token) {
  return new Promise((resolve) => {
    const req = https.request({
      hostname: 'api.line.me',
      path: `/v2/bot/profile/${userId}`,
      method: 'GET',
      headers: { Authorization: `Bearer ${token}` },
    }, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => {
        try {
          if (res.statusCode === 200) resolve(JSON.parse(body));
          else resolve(null);
        } catch (e) { resolve(null); }
      });
    });
    req.on('error', () => resolve(null));
    req.end();
  });
}

function isBniTainanLineDirect(event, ctx) {
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  return sessionKey.includes('bni_tainan') && sessionKey.includes('line') && sessionKey.includes('direct');
}

function extractUserId(event, ctx) {
  const raw = event.from ?? event.senderId ?? ctx.from ?? ctx.senderId ?? '';
  let id = String(raw);
  if (id.startsWith('line:')) id = id.slice('line:'.length);
  if (!id) {
    const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
    const parts = sessionKey.split(':');
    id = parts[parts.length - 1] || '';
  }
  return id; // e.g. u895a0ad8e49d75f8303dc3d067282dc0
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'received') return;

  const ctx = event.context ?? {};
  if (!isBniTainanLineDirect(event, ctx)) return;

  const userIdLower = extractUserId(event, ctx);
  if (!userIdLower) return;

  const map = loadMap();
  if (map[userIdLower]) return; // 已記錄過，不重複查

  let token;
  try {
    token = fs.readFileSync(TOKEN_FILE, 'utf8').trim();
  } catch (e) { return; }

  const userIdForApi = 'U' + userIdLower.replace(/^u/i, '');
  const profile = await fetchLineProfile(userIdForApi, token);
  if (!profile) return;

  const { guessedMember, confidence } = guessMember(profile.displayName, profile.statusMessage);

  map[userIdLower] = {
    userId: userIdLower,
    displayName: profile.displayName || '',
    statusMessage: profile.statusMessage || '',
    guessedMember,
    confidence,
    firstSeenAt: new Date().toISOString(),
  };
  saveMap(map);
};

module.exports = handler;
module.exports.default = handler;

